def list_formulas(category: str | None = None, status: str | None = None) -> list[dict]:
    rows = [dict(x) for x in FORMULAS]
    if category:
        rows = [x for x in rows if x["category"] == category]
    if status:
        rows = [x for x in rows if x["status"] == status]
    return rows


def get_formula(formula_id: str) -> dict | None:
    item = next((x for x in FORMULAS if x["id"] == formula_id), None)
    return dict(item) if item else None
